/* C API of the Rust port of `modified_md5.c`, generated by rust-anything. */
#ifndef MODIFIED_MD5_RS_H
#define MODIFIED_MD5_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

uint32_t F(uint32_t B, uint32_t C, uint32_t D);
uint32_t G(uint32_t B, uint32_t C, uint32_t D);
uint32_t H(uint32_t B, uint32_t C, uint32_t D);
uint32_t I(uint32_t B, uint32_t C, uint32_t D);
uint32_t rol(uint32_t input, int count);
void swap(uint32_t *a, uint32_t *b);
void modified_md5(unsigned char *block, unsigned char *key, unsigned char *output);

/* The same functions under `rust_anything_` names, for shadow runs. */
uint32_t rust_anything_F(uint32_t B, uint32_t C, uint32_t D);
uint32_t rust_anything_G(uint32_t B, uint32_t C, uint32_t D);
uint32_t rust_anything_H(uint32_t B, uint32_t C, uint32_t D);
uint32_t rust_anything_I(uint32_t B, uint32_t C, uint32_t D);
uint32_t rust_anything_rol(uint32_t input, int count);
void rust_anything_swap(uint32_t *a, uint32_t *b);
void rust_anything_modified_md5(unsigned char *block, unsigned char *key, unsigned char *output);

#endif /* MODIFIED_MD5_RS_H */
